"use client";

import { useEffect, useRef } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

if (typeof window !== "undefined") {
  gsap.registerPlugin(ScrollTrigger);
}

type Step = {
  place: string;
  years: string;
  text: string;
  note: string;
  mood: "up" | "down" | "turn";
};

const STEPS: Step[] = [
  {
    place: "TCS · Belgium",
    years: "The start",
    note: "First step abroad",
    text: "My career begins in Europe. I'm growing professionally, living abroad, building a solid life on paper. It feels like everything is going well.",
    mood: "up",
  },
  {
    place: "Belgium & Luxembourg",
    years: "3 years",
    note: "Something is missing",
    text: "I travel across Europe, and the journeys slowly turn inward. Difficult questions about purpose, direction, and what truly matters start surfacing.",
    mood: "down",
  },
  {
    place: "Back to India",
    years: "The leap",
    note: "No plan. No savings.",
    text: "With a strong conviction and an early habit of investing — but no concrete plan — I decide to return to India. That decision changes everything.",
    mood: "turn",
  },
  {
    place: "IIIT Bangalore",
    years: "Turning point",
    note: "Data Science",
    text: "On a mentor's suggestion, I apply for the Data Science program. Getting through was a milestone, but the year there transforms how I think, learn, and solve.",
    mood: "up",
  },
  {
    place: "The Netherlands",
    years: "7+ years",
    note: "Data & AI Expert",
    text: "I return to Europe and spend over seven years working as a Data & AI Expert — while discovering a deep desire to write, reflect, and share.",
    mood: "up",
  },
  {
    place: "Author",
    years: "The books",
    note: "Writing alongside work",
    text: "That journey of sharing leads me to author books alongside my work. Today my story sits at the intersection of technology, self-discovery, and lifelong learning.",
    mood: "up",
  },
];

function MoodDot({ mood }: { mood: Step["mood"] }) {
  if (mood === "down") {
    return (
      <span className="inline-flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">
        <span className="h-1.5 w-1.5 rounded-full bg-muted-foreground" />
        A low point
      </span>
    );
  }
  if (mood === "turn") {
    return (
      <span className="inline-flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wider text-accent-strong">
        <span className="h-1.5 w-1.5 rounded-full bg-accent" />
        The turn
      </span>
    );
  }
  return (
    <span className="inline-flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wider text-blue-700 dark:text-blue-400">
      <span className="h-1.5 w-1.5 rounded-full bg-blue-700" />
      A high point
    </span>
  );
}

export function JourneyTimeline() {
  const root = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = root.current;
    if (!el) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

    const ctx = gsap.context(() => {
      const spine = el.querySelector<HTMLElement>("[data-spine]");
      const wrap = el.querySelector<HTMLElement>("[data-spine-wrap]");
      const steps = gsap.utils.toArray<HTMLElement>("[data-step]");
      const isDesktop = window.matchMedia("(min-width: 768px)").matches;

      if (spine && wrap) {
        const lis = steps
          .map((s) => s.closest("li"))
          .filter(Boolean) as HTMLLIElement[];

        const docTop = () => wrap.getBoundingClientRect().top + window.scrollY;
        const last = lis[lis.length - 1];

        // Draw the line so it begins filling exactly when the first dot
        // enters the viewport and completes exactly when the last card has
        // finished revealing (its top reaches 40% from the viewport top) —
        // the same end point the cards themselves scrub to. Because it's
        // scrubbed, it reverses perfectly on scroll up, and the tip flips
        // each dot the moment the line reaches it.
        gsap.fromTo(
          spine,
          { scaleY: 0 },
          {
            scaleY: 1,
            ease: "none",
            transformOrigin: "top center",
            scrollTrigger: {
              trigger: wrap,
              start: () => docTop() - window.innerHeight,
              end: () =>
                docTop() + last.offsetTop - 0.4 * window.innerHeight,
              scrub: 0.3,
              onUpdate: (self) => {
                const tip = self.progress * wrap.offsetHeight;
                lis.forEach((li) => {
                  li.classList.toggle("is-active", li.offsetTop <= tip);
                });
              },
            },
          }
        );
      }

      // Cards slide in scrubbed to the line: they fade up and glide into
      // place as the progressive spine reaches them, and reverse smoothly
      // when scrolling back up — so they never feel static.
      steps.forEach((step, i) => {
        const x = isDesktop ? (i % 2 === 0 ? 32 : -32) : 0;
        gsap.fromTo(
          step,
          { opacity: 0, x, y: 40 },
          {
            opacity: 1,
            x: 0,
            y: 0,
            ease: "none",
            scrollTrigger: {
              trigger: step,
              start: "top bottom",
              end: "top 40%",
              scrub: 0.4,
            },
          }
        );

        // Dot pops in the same scrubbed motion, in sync with its card.
        const dot = step.querySelector("[data-dot]");
        if (dot) {
          gsap.fromTo(
            dot,
            { scale: 0 },
            {
              scale: 1,
              ease: "none",
              scrollTrigger: {
                trigger: step,
                start: "top bottom",
                end: "top 40%",
                scrub: 0.4,
              },
            }
          );
        }
      });
    }, el);

    // ScrollTrigger measured positions before fonts/images settled, which on
    // mobile can leave below-fold content at opacity 0. Recalibrate once
    // layout is stable so every trigger fires exactly where it should.
    const refresh = () => ScrollTrigger.refresh();
    window.setTimeout(refresh, 0);
    if (document.fonts?.ready) {
      document.fonts.ready.then(refresh).catch(() => {});
    }

    return () => ctx.revert();
  }, []);

  return (
    <section ref={root} className="py-20 md:py-28 border-b border-border" aria-label="The journey of my 20s">
      <div className="mx-auto max-w-6xl px-4 sm:px-6">
        <div className="max-w-2xl">
          <p data-reveal className="text-xs font-semibold uppercase tracking-[0.2em] text-accent-strong">
            My 20s
          </p>
          <h2
            data-reveal
            className="mt-3 font-display text-3xl md:text-5xl font-bold tracking-tight"
          >
            A journey of{" "}
            <span className="text-muted-foreground">highs and lows</span>
          </h2>
          <p
            data-reveal
            className="mt-5 text-muted-foreground leading-relaxed"
          >
            It wasn&apos;t a straight line. It was a winding path of momentum,
            doubt, and leaps of faith — each low quietly building the next
            high.
          </p>
        </div>

        <div className="relative mt-16" data-spine-wrap>
          {/* Spine track */}
          <div
            className="absolute left-5 md:left-1/2 top-0 bottom-0 w-[3px] -translate-x-1/2 rounded-full bg-muted-foreground/25"
            aria-hidden="true"
          />
          <div
            data-spine
            className="absolute left-5 md:left-1/2 top-0 bottom-0 w-[3px] -translate-x-1/2 rounded-full bg-accent"
            aria-hidden="true"
          />

          <ol className="space-y-14 md:space-y-20">
            {STEPS.map((step, i) => {
              const left = i % 2 === 0;
              return (
                <li key={step.place} className="relative">
                  {/* Dot on the spine */}
                  <span
                    data-dot
                    className="absolute left-5 md:left-1/2 top-1.5 z-10 h-4 w-4 -translate-x-1/2 rounded-full bg-muted-foreground ring-4 ring-background"
                    aria-hidden="true"
                  />

                  <div
                    data-step
                    className={`grid grid-cols-1 gap-3 pl-14 md:pl-0 md:grid-cols-2 ${
                      left ? "" : "md:justify-items-end"
                    }`}
                  >
                    <div
                      className={`${
                        left
                          ? "md:pr-16 md:text-right"
                          : "md:col-start-2 md:pl-16"
                      }`}
                    >
                      <div
                        className={`group rounded-3xl border border-border bg-card p-6 sm:p-7 transition-all duration-500 hover:-translate-y-1 hover:shadow-xl ${
                          step.mood === "down"
                            ? "hover:border-muted-foreground/40"
                            : "hover:border-brand-light/60"
                        }`}
                      >
                        <p className="text-[11px] font-semibold uppercase tracking-[0.18em] text-accent-strong">
                          {step.years}
                        </p>
                        <h3 className="mt-2 font-display text-xl sm:text-2xl font-bold">
                          {step.place}
                        </h3>
                        <div className="mt-2">
                          <MoodDot mood={step.mood} />
                        </div>
                        <p className="mt-3 text-sm text-muted-foreground leading-relaxed">
                          {step.text}
                        </p>
                      </div>
                    </div>
                  </div>
                </li>
              );
            })}
          </ol>
        </div>

        <p
          data-reveal
          className="mt-16 max-w-3xl font-serif text-lg italic text-muted-foreground leading-relaxed"
        >
          Today, my story sits at the intersection of technology,
          self-discovery, and lifelong learning — and it&apos;s still
          unfolding.
        </p>
      </div>
    </section>
  );
}
